<?php
return static function(Database $db): void {$db->pdo->exec('CREATE TABLE IF NOT EXISTS rate_limit_events(bucket_hash CHAR(64) NOT NULL,bucket VARCHAR(64) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_rate_limit_bucket_time(bucket_hash,bucket,created_at)) ENGINE=InnoDB');$db->pdo->exec('CREATE TABLE IF NOT EXISTS security_audit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,occurred_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,event VARCHAR(64) NOT NULL,result VARCHAR(32) NOT NULL,pc_id VARCHAR(64) NULL,device_id VARCHAR(64) NULL,request_id VARCHAR(64) NULL,ip_hash CHAR(64) NULL,metadata_json JSON NULL,KEY idx_audit_time(occurred_at)) ENGINE=InnoDB');};
